    let activation: AiConsoleCapabilityActivationRecord | null = null; let candidate: AiConsoleRuntimeFrameCandidateRecord | null = null; let publication: AiConsoleRuntimeFramePublicationRecord | null = null; let event: AiConsoleRuntimeReleaseEventRecord | null = null
    let targetIdentity: string | null = null; let resultTerminalId: AiConsoleRuntimeReleaseCommandReceipt["resultTerminalId"]; let failureCode: string | null = null; let resultingRegistryRevision = metadata.registryRevision; let creationContentBlob: Uint8Array | null = null

    if (input.expectedRegistryRevision !== metadata.registryRevision) { resultTerminalId = "registry_revision_conflict"; failureCode = "ai_console_runtime_release_registry_revision_conflict" }
