      if (!sourceActivation) { targetIdentity = input.activationId; resultTerminalId = "activation_not_found"; failureCode = "ai_console_capability_activation_not_found" }
      else if (readCurrentActivation(database, sourceActivation.capabilityDomain)?.activationId !== sourceActivation.activationId) { targetIdentity = sourceActivation.activationId; activation = sourceActivation; resultTerminalId = "activation_not_current"; failureCode = "ai_console_capability_activation_not_current" }
