      const review = reviewStore.reviewResults.find((item) => item.reviewResultId === input.reviewResultId) ?? null
      if (!sourceCandidate) { targetIdentity = input.runtimeFrameCandidateIdentity; resultTerminalId = "runtime_frame_candidate_not_found"; failureCode = "ai_console_runtime_frame_candidate_not_found" }
      else if (!review) { targetIdentity = input.reviewResultId; candidate = sourceCandidate; resultTerminalId = "review_result_not_found"; failureCode = "ai_console_runtime_review_result_not_found" }
