function normalizedCommandInput(input: AiConsoleRuntimeReleaseCommandInput) { const { actorIdentity: _a, role: _r, requestedAtUtc: _t, idempotencyKeySha256: _k, ...rest } = input; void _a; void _r; void _t; void _k; return rest }

function openWritableStore() { const storePath = getStorePath(); mkdirSync(path.dirname(storePath), { recursive: true }); const d = new DatabaseSync(storePath); d.exec("PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000; PRAGMA journal_mode=DELETE; PRAGMA synchronous=FULL;"); d.exec(`
CREATE TABLE IF NOT EXISTS metadata (singleton INTEGER PRIMARY KEY CHECK(singleton=1), schema_version TEXT NOT NULL, registry_identity TEXT NOT NULL, source_boundary TEXT NOT NULL, writer_identity TEXT NOT NULL, store_revision INTEGER NOT NULL, registry_revision INTEGER NOT NULL, activation_count INTEGER NOT NULL, candidate_count INTEGER NOT NULL, publication_count INTEGER NOT NULL, command_count INTEGER NOT NULL, event_count INTEGER NOT NULL, created_at_utc TEXT NOT NULL, updated_at_utc TEXT NOT NULL, head_event_record_sha256 TEXT, head_command_receipt_sha256 TEXT, metadata_sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS capability_activations (activation_id TEXT PRIMARY KEY, activation_sequence INTEGER NOT NULL UNIQUE, capability_domain TEXT NOT NULL, capability_release_identity TEXT NOT NULL, capability_release_record_sha256 TEXT NOT NULL, capability_version_id TEXT NOT NULL, qualification_set_sha256 TEXT NOT NULL, condition_schema_id TEXT NOT NULL, previous_activation_id TEXT, activation_status TEXT NOT NULL, command_id TEXT NOT NULL UNIQUE, activated_at_utc TEXT NOT NULL, creation_content_sha256 TEXT NOT NULL, creation_content_blob BLOB NOT NULL, activation_record_sha256 TEXT NOT NULL, FOREIGN KEY(previous_activation_id) REFERENCES capability_activations(activation_id));
CREATE TABLE IF NOT EXISTS runtime_frame_candidates (runtime_frame_candidate_identity TEXT PRIMARY KEY, candidate_sequence INTEGER NOT NULL UNIQUE, activation_id TEXT NOT NULL, activation_record_sha256 TEXT NOT NULL, capability_domain TEXT NOT NULL, capability_release_identity TEXT NOT NULL, world_id TEXT NOT NULL, tick INTEGER NOT NULL, world_fact_identity TEXT NOT NULL, condition_package_identity TEXT NOT NULL, visual_artifact_identity TEXT NOT NULL, image_sha256 TEXT NOT NULL, frame_manifest_sha256 TEXT NOT NULL, candidate_status TEXT NOT NULL, command_id TEXT NOT NULL UNIQUE, registered_at_utc TEXT NOT NULL, creation_content_sha256 TEXT NOT NULL, creation_content_blob BLOB NOT NULL, candidate_record_sha256 TEXT NOT NULL, FOREIGN KEY(activation_id) REFERENCES capability_activations(activation_id));
CREATE TABLE IF NOT EXISTS runtime_frame_publications (publish_identity TEXT PRIMARY KEY, publication_sequence INTEGER NOT NULL UNIQUE, runtime_frame_identity TEXT NOT NULL UNIQUE, runtime_frame_candidate_identity TEXT NOT NULL UNIQUE, candidate_record_sha256 TEXT NOT NULL, activation_id TEXT NOT NULL, capability_domain TEXT NOT NULL, capability_release_identity TEXT NOT NULL, world_id TEXT NOT NULL, tick INTEGER NOT NULL, review_result_id TEXT NOT NULL UNIQUE, review_result_record_sha256 TEXT NOT NULL, review_contract_id TEXT NOT NULL, previous_runtime_frame_identity TEXT, runtime_frame_status TEXT NOT NULL, command_id TEXT NOT NULL UNIQUE, published_at_utc TEXT NOT NULL, creation_content_sha256 TEXT NOT NULL, creation_content_blob BLOB NOT NULL, publication_record_sha256 TEXT NOT NULL, UNIQUE(world_id,tick), FOREIGN KEY(runtime_frame_candidate_identity) REFERENCES runtime_frame_candidates(runtime_frame_candidate_identity));
CREATE TABLE IF NOT EXISTS runtime_release_events (runtime_release_event_id TEXT PRIMARY KEY, event_sequence INTEGER NOT NULL UNIQUE, command_id TEXT NOT NULL UNIQUE, event_type TEXT NOT NULL, subject_type TEXT NOT NULL, subject_identity TEXT NOT NULL, capability_domain TEXT NOT NULL, subject_record_sha256 TEXT NOT NULL, occurred_at_utc TEXT NOT NULL, previous_event_record_sha256 TEXT, event_record_sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS command_receipts (command_id TEXT PRIMARY KEY, command_sequence INTEGER NOT NULL UNIQUE, command_type TEXT NOT NULL, actor_identity TEXT NOT NULL, role TEXT NOT NULL, target_identity TEXT, expected_registry_revision INTEGER NOT NULL, resulting_registry_revision INTEGER NOT NULL, idempotency_key_sha256 TEXT NOT NULL, input_sha256 TEXT NOT NULL, reason_text TEXT NOT NULL, validation_status TEXT NOT NULL, execution_status TEXT NOT NULL, result_terminal_id TEXT NOT NULL, failure_code TEXT, event_id TEXT, requested_at_utc TEXT NOT NULL, finished_at_utc TEXT NOT NULL, executor_identity TEXT NOT NULL, previous_command_receipt_sha256 TEXT, command_receipt_sha256 TEXT NOT NULL);`); const count = Number((d.prepare("SELECT COUNT(*) count FROM metadata").get() as { count: number }).count); if (count === 0) insertInitialMetadata(d); if (count > 1) throw new Error("ai_console_runtime_release_metadata_cardinality_invalid"); d.exec("PRAGMA user_version=1"); verifyDatabase(d); return d }
function insertInitialMetadata(d: DatabaseSync) { const createdAtUtc = new Date().toISOString(); const unsigned: Omit<AiConsoleRuntimeReleaseMetadata, "metadataSha256"> = { schemaVersion, registryIdentity, sourceBoundary: "new_ai_console_only", writerIdentity, storeRevision: 0, registryRevision: 0, activationCount: 0, candidateCount: 0, publicationCount: 0, commandCount: 0, eventCount: 0, createdAtUtc, updatedAtUtc: createdAtUtc, headEventRecordSha256: null, headCommandReceiptSha256: null }; const m = { ...unsigned, metadataSha256: sha256(JSON.stringify(unsigned)) }; d.prepare("INSERT INTO metadata VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(m.schemaVersion,m.registryIdentity,m.sourceBoundary,m.writerIdentity,m.storeRevision,m.registryRevision,m.activationCount,m.candidateCount,m.publicationCount,m.commandCount,m.eventCount,m.createdAtUtc,m.updatedAtUtc,m.headEventRecordSha256,m.headCommandReceiptSha256,m.metadataSha256) }
function insertActivation(d: DatabaseSync,r:AiConsoleCapabilityActivationRecord,b:Uint8Array){d.prepare("INSERT INTO capability_activations VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(r.activationId,r.activationSequence,r.capabilityDomain,r.capabilityReleaseIdentity,r.capabilityReleaseRecordSha256,r.capabilityVersionId,r.qualificationSetSha256,r.conditionSchemaId,r.previousActivationId,r.activationStatus,r.commandId,r.activatedAtUtc,r.creationContentSha256,b,r.activationRecordSha256)}
function insertCandidate(d:DatabaseSync,r:AiConsoleRuntimeFrameCandidateRecord,b:Uint8Array){d.prepare("INSERT INTO runtime_frame_candidates VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(r.runtimeFrameCandidateIdentity,r.candidateSequence,r.activationId,r.activationRecordSha256,r.capabilityDomain,r.capabilityReleaseIdentity,r.worldId,r.tick,r.worldFactIdentity,r.conditionPackageIdentity,r.visualArtifactIdentity,r.imageSha256,r.frameManifestSha256,r.candidateStatus,r.commandId,r.registeredAtUtc,r.creationContentSha256,b,r.candidateRecordSha256)}
function insertPublication(d:DatabaseSync,r:AiConsoleRuntimeFramePublicationRecord,b:Uint8Array){d.prepare("INSERT INTO runtime_frame_publications VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(r.publishIdentity,r.publicationSequence,r.runtimeFrameIdentity,r.runtimeFrameCandidateIdentity,r.candidateRecordSha256,r.activationId,r.capabilityDomain,r.capabilityReleaseIdentity,r.worldId,r.tick,r.reviewResultId,r.reviewResultRecordSha256,r.reviewContractId,r.previousRuntimeFrameIdentity,r.runtimeFrameStatus,r.commandId,r.publishedAtUtc,r.creationContentSha256,b,r.publicationRecordSha256)}
