function insertReceipt(d:DatabaseSync,r:AiConsoleRuntimeReleaseCommandReceipt){d.prepare("INSERT INTO command_receipts VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(r.commandId,r.commandSequence,r.commandType,r.actorIdentity,r.role,r.targetIdentity,r.expectedRegistryRevision,r.resultingRegistryRevision,r.idempotencyKeySha256,r.inputSha256,r.reasonText,r.validationStatus,r.executionStatus,r.resultTerminalId,r.failureCode,r.eventId,r.requestedAtUtc,r.finishedAtUtc,r.executorIdentity,r.previousCommandReceiptSha256,r.commandReceiptSha256)}
function updateMetadata(d:DatabaseSync,m:AiConsoleRuntimeReleaseMetadata,r:AiConsoleRuntimeReleaseCommandReceipt,e:AiConsoleRuntimeReleaseEventRecord|null){const unsigned:Omit<AiConsoleRuntimeReleaseMetadata,"metadataSha256">={schemaVersion,registryIdentity,sourceBoundary:"new_ai_console_only",writerIdentity,storeRevision:m.storeRevision+1,registryRevision:r.resultingRegistryRevision,activationCount:m.activationCount+(e?.eventType==="capability_release_activated"?1:0),candidateCount:m.candidateCount+(e?.eventType==="runtime_frame_candidate_registered"?1:0),publicationCount:m.publicationCount+(e?.eventType==="reviewed_runtime_frame_published"?1:0),commandCount:m.commandCount+1,eventCount:m.eventCount+(e?1:0),createdAtUtc:m.createdAtUtc,updatedAtUtc:r.finishedAtUtc,headEventRecordSha256:e?.eventRecordSha256??m.headEventRecordSha256,headCommandReceiptSha256:r.commandReceiptSha256};const next={...unsigned,metadataSha256:sha256(JSON.stringify(unsigned))};d.prepare("UPDATE metadata SET store_revision=?,registry_revision=?,activation_count=?,candidate_count=?,publication_count=?,command_count=?,event_count=?,updated_at_utc=?,head_event_record_sha256=?,head_command_receipt_sha256=?,metadata_sha256=? WHERE singleton=1").run(next.storeRevision,next.registryRevision,next.activationCount,next.candidateCount,next.publicationCount,next.commandCount,next.eventCount,next.updatedAtUtc,next.headEventRecordSha256,next.headCommandReceiptSha256,next.metadataSha256)}

