function readAndVerifyMetadata(d:DatabaseSync){const r=d.prepare("SELECT * FROM metadata WHERE singleton=1").get() as Record<string,unknown>|undefined;if(!r)throw new Error("ai_console_runtime_release_metadata_missing");const m:AiConsoleRuntimeReleaseMetadata={schemaVersion:String(r.schema_version) as typeof schemaVersion,registryIdentity:String(r.registry_identity) as typeof registryIdentity,sourceBoundary:String(r.source_boundary) as "new_ai_console_only",writerIdentity:String(r.writer_identity) as typeof writerIdentity,storeRevision:Number(r.store_revision),registryRevision:Number(r.registry_revision),activationCount:Number(r.activation_count),candidateCount:Number(r.candidate_count),publicationCount:Number(r.publication_count),commandCount:Number(r.command_count),eventCount:Number(r.event_count),createdAtUtc:String(r.created_at_utc),updatedAtUtc:String(r.updated_at_utc),headEventRecordSha256:r.head_event_record_sha256===null?null:String(r.head_event_record_sha256),headCommandReceiptSha256:r.head_command_receipt_sha256===null?null:String(r.head_command_receipt_sha256),metadataSha256:String(r.metadata_sha256)};const{metadataSha256,...unsigned}=m;if(m.schemaVersion!==schemaVersion||m.registryIdentity!==registryIdentity||m.sourceBoundary!=="new_ai_console_only"||m.writerIdentity!==writerIdentity||sha256(JSON.stringify(unsigned))!==metadataSha256)throw new Error("ai_console_runtime_release_metadata_invalid");return m}
function activationFromRow(v:unknown):StoredActivation{const r=v as Record<string,unknown>;return{schemaVersion:"ai_console_capability_activation_v1",registryIdentity,activationId:String(r.activation_id),activationSequence:Number(r.activation_sequence),capabilityDomain:String(r.capability_domain) as AiConsoleCapabilityDomain,capabilityReleaseIdentity:String(r.capability_release_identity),capabilityReleaseRecordSha256:String(r.capability_release_record_sha256),capabilityVersionId:String(r.capability_version_id),qualificationSetSha256:String(r.qualification_set_sha256),conditionSchemaId:String(r.condition_schema_id),previousActivationId:r.previous_activation_id===null?null:String(r.previous_activation_id),activationStatus:"activated",commandId:String(r.command_id),activatedAtUtc:String(r.activated_at_utc),creationContentSha256:String(r.creation_content_sha256),creationContentBlob:r.creation_content_blob as Uint8Array,activationRecordSha256:String(r.activation_record_sha256)}}
function candidateFromRow(v:unknown):StoredCandidate{const r=v as Record<string,unknown>;return{schemaVersion:"ai_console_runtime_frame_candidate_v1",registryIdentity,runtimeFrameCandidateIdentity:String(r.runtime_frame_candidate_identity),candidateSequence:Number(r.candidate_sequence),activationId:String(r.activation_id),activationRecordSha256:String(r.activation_record_sha256),capabilityDomain:String(r.capability_domain) as AiConsoleCapabilityDomain,capabilityReleaseIdentity:String(r.capability_release_identity),worldId:String(r.world_id),tick:Number(r.tick),worldFactIdentity:String(r.world_fact_identity),conditionPackageIdentity:String(r.condition_package_identity),visualArtifactIdentity:String(r.visual_artifact_identity),imageSha256:String(r.image_sha256),frameManifestSha256:String(r.frame_manifest_sha256),candidateStatus:"registered_for_review",commandId:String(r.command_id),registeredAtUtc:String(r.registered_at_utc),creationContentSha256:String(r.creation_content_sha256),creationContentBlob:r.creation_content_blob as Uint8Array,candidateRecordSha256:String(r.candidate_record_sha256)}}
