function readActivationById(d:DatabaseSync,id:string){const r=d.prepare(`${activationSelectSql} WHERE activation_id=?`).get(id);return r?stripBlob(activationFromRow(r)):null} function readCurrentActivation(d:DatabaseSync,domain:string){const r=d.prepare(`${activationSelectSql} WHERE capability_domain=? ORDER BY activation_sequence DESC LIMIT 1`).get(domain);return r?stripBlob(activationFromRow(r)):null} function readCandidateById(d:DatabaseSync,id:string){const r=d.prepare(`${candidateSelectSql} WHERE runtime_frame_candidate_identity=?`).get(id);return r?stripBlob(candidateFromRow(r)):null} function readPublicationByCandidate(d:DatabaseSync,id:string){const r=d.prepare(`${publicationSelectSql} WHERE runtime_frame_candidate_identity=?`).get(id);return r?stripBlob(publicationFromRow(r)):null} function readPublicationByTarget(d:DatabaseSync,id:string){const r=d.prepare(`${publicationSelectSql} WHERE publish_identity=? OR runtime_frame_identity=?`).get(id,id);return r?stripBlob(publicationFromRow(r)):null} function readPublicationByWorldTick(d:DatabaseSync,w:string,t:number){const r=d.prepare(`${publicationSelectSql} WHERE world_id=? AND tick=?`).get(w,t);return r?stripBlob(publicationFromRow(r)):null} function readLatestPublicationForWorld(d:DatabaseSync,w:string){const r=d.prepare(`${publicationSelectSql} WHERE world_id=? ORDER BY publication_sequence DESC LIMIT 1`).get(w);return r?stripBlob(publicationFromRow(r)):null} function readEventById(d:DatabaseSync,id:string){const r=d.prepare(`${eventSelectSql} WHERE runtime_release_event_id=?`).get(id);return r?eventFromRow(r):null}
function stripBlob<T extends {creationContentBlob?:Uint8Array}>(r:T):Omit<T,"creationContentBlob">{const{creationContentBlob:_b,...record}=r;void _b;return record}

