function verifyDatabase(d:DatabaseSync){const integrity=d.prepare("PRAGMA integrity_check").get();if(!integrity||!Object.values(integrity).includes("ok"))throw new Error("ai_console_runtime_release_sqlite_integrity_failed");if(Number((d.prepare("PRAGMA user_version").get() as Record<string,unknown>).user_version)!==1)throw new Error("ai_console_runtime_release_store_version_invalid");const tables=(d.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all() as {name:string}[]).map((row)=>row.name);const expectedTables=Object.keys(expectedTableColumns).sort();if(JSON.stringify(tables)!==JSON.stringify(expectedTables))throw new Error("ai_console_runtime_release_table_set_invalid");for(const[table,columns]of Object.entries(expectedTableColumns)){const actual=(d.prepare(`PRAGMA table_info(${table})`).all() as {name:string}[]).map((row)=>row.name);if(JSON.stringify(actual)!==JSON.stringify(columns))throw new Error(`ai_console_runtime_release_table_columns_invalid:${table}`)}}
function verifyRecords(m:AiConsoleRuntimeReleaseMetadata,a:StoredActivation[],c:StoredCandidate[],p:StoredPublication[],e:AiConsoleRuntimeReleaseEventRecord[],r:AiConsoleRuntimeReleaseCommandReceipt[]){if(a.length!==m.activationCount||c.length!==m.candidateCount||p.length!==m.publicationCount||e.length!==m.eventCount||r.length!==m.commandCount||m.registryRevision!==a.length+c.length+p.length||m.storeRevision!==r.length)throw new Error("ai_console_runtime_release_metadata_count_mismatch");const previousActivationByDomain=new Map<AiConsoleCapabilityDomain,string>();for(const[x,i]of a.entries()){const previousA=previousActivationByDomain.get(i.capabilityDomain)??null;if(i.activationSequence!==x+1||i.previousActivationId!==previousA)throw new Error("ai_console_runtime_release_activation_chain_invalid");const blob=Buffer.from(i.creationContentBlob).toString("utf8");if(sha256(blob)!==i.creationContentSha256)throw new Error("ai_console_runtime_release_activation_blob_invalid");const{creationContentBlob:_b,activationRecordSha256,...unsigned}=i;void _b;if(sha256(JSON.stringify(unsigned))!==activationRecordSha256)throw new Error("ai_console_runtime_release_activation_sha256_mismatch");previousActivationByDomain.set(i.capabilityDomain,i.activationId)}for(const[x,i]of c.entries()){if(i.candidateSequence!==x+1)throw new Error("ai_console_runtime_release_candidate_sequence_invalid");const blob=Buffer.from(i.creationContentBlob).toString("utf8");if(sha256(blob)!==i.creationContentSha256)throw new Error("ai_console_runtime_release_candidate_blob_invalid");const{creationContentBlob:_b,candidateRecordSha256,...unsigned}=i;void _b;if(sha256(JSON.stringify(unsigned))!==candidateRecordSha256||!a.some(v=>v.activationId===i.activationId&&v.activationRecordSha256===i.activationRecordSha256))throw new Error("ai_console_runtime_release_candidate_binding_invalid")}for(const[x,i]of p.entries()){if(i.publicationSequence!==x+1)throw new Error("ai_console_runtime_release_publication_sequence_invalid");const blob=Buffer.from(i.creationContentBlob).toString("utf8");if(sha256(blob)!==i.creationContentSha256)throw new Error("ai_console_runtime_release_publication_blob_invalid");const{creationContentBlob:_b,publicationRecordSha256,...unsigned}=i;void _b;if(sha256(JSON.stringify(unsigned))!==publicationRecordSha256||!c.some(v=>v.runtimeFrameCandidateIdentity===i.runtimeFrameCandidateIdentity&&v.candidateRecordSha256===i.candidateRecordSha256))throw new Error("ai_console_runtime_release_publication_binding_invalid")}let pe:string|null=null;for(const[x,i]of e.entries()){if(i.eventSequence!==x+1||i.previousEventRecordSha256!==pe)throw new Error("ai_console_runtime_release_event_chain_invalid");const{eventRecordSha256,...unsigned}=i;if(sha256(JSON.stringify(unsigned))!==eventRecordSha256)throw new Error("ai_console_runtime_release_event_sha256_mismatch");pe=i.eventRecordSha256}let pr:string|null=null;for(const[x,i]of r.entries()){if(i.commandSequence!==x+1||i.previousCommandReceiptSha256!==pr)throw new Error("ai_console_runtime_release_receipt_chain_invalid");const{commandReceiptSha256,...unsigned}=i;if(sha256(JSON.stringify(unsigned))!==commandReceiptSha256)throw new Error("ai_console_runtime_release_receipt_sha256_mismatch");pr=i.commandReceiptSha256}if(m.headEventRecordSha256!==pe||m.headCommandReceiptSha256!==pr)throw new Error("ai_console_runtime_release_head_mismatch")}
function verifyExternalBindings(a:StoredActivation[],p:StoredPublication[]){const cs=readAiConsoleCapabilityLifecycleStore();const rs=readAiConsoleReviewAdjudicationStore();if(cs.status!=="connected"||rs.status!=="connected")throw new Error("ai_console_runtime_release_external_source_unavailable");for(const x of a){if(!cs.releases.some(v=>v.capabilityReleaseIdentity===x.capabilityReleaseIdentity&&v.releaseRecordSha256===x.capabilityReleaseRecordSha256&&v.qualificationSetSha256===x.qualificationSetSha256))throw new Error("ai_console_runtime_release_capability_binding_invalid")}for(const x of p){if(!rs.reviewResults.some(v=>v.reviewResultId===x.reviewResultId&&v.reviewResultRecordSha256===x.reviewResultRecordSha256&&v.reviewStatus==="passed"&&v.validationInputIdentity===x.runtimeFrameCandidateIdentity))throw new Error("ai_console_runtime_release_review_binding_invalid")}}
function getStorePath(){return path.join(process.cwd(),...runtimeReleaseRegistryStoreLogicalPath.split("/"))} function sha256(v:string){return createHash("sha256").update(v,"utf8").digest("hex")} function isSha256(v:unknown):v is string{return typeof v==="string"&&/^[a-f0-9]{64}$/u.test(v)} function isIdentity(v:unknown):v is string{return typeof v==="string"&&/^[A-Za-z0-9][A-Za-z0-9._:/-]{2,159}$/u.test(v)} function isText(v:unknown,min:number,max:number):v is string{return typeof v==="string"&&v===v.trim()&&v.length>=min&&v.length<=max&&!/[\u0000-\u001f\u007f]/u.test(v)} function isUtc(v:unknown):v is string{return typeof v==="string"&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString()===v} function isPlainRecord(v:unknown):v is Record<string,unknown>{return typeof v==="object"&&v!==null&&!Array.isArray(v)}
